<?php
declare(strict_types=1);
ini_set('display_errors','0');
session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();
header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');
function fail(string $m,int $code=400):void{http_response_code($code);echo json_encode(['error'=>$m]);exit;}
if($_SERVER['REQUEST_METHOD']!=='POST')fail('POST required.',405);
// JSON-only requests plus same-origin checks prevent cross-site form submissions.
if(stripos($_SERVER['CONTENT_TYPE']??'','application/json')!==0)fail('JSON required.',415);
if(isset($_SERVER['HTTP_ORIGIN'])){ $origin=parse_url($_SERVER['HTTP_ORIGIN']);$host=parse_url('http://'.($_SERVER['HTTP_HOST']??''));if(($origin['host']??'')!==($host['host']??'')||($origin['port']??null)!==($host['port']??null))fail('Origin rejected.',403);}
if((int)($_SERVER['CONTENT_LENGTH']??0)>9000000)fail('Upload too large.',413);
$p=json_decode(file_get_contents('php://input'),true);if(!is_array($p))fail('Invalid request.');$action=$_GET['action']??'';
function field(array $p,string $k,int $max=3000):string{$v=trim((string)($p[$k]??''));if($v===''||strlen($v)>$max)fail('Please check '.$k.'.');return $v;}
function publicUser(array $u):array{unset($u['password_hash']);$u['id']=(int)$u['id'];return $u;}
try{
$c=require __DIR__.'/config.php';$db=new PDO($c['dsn'],$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
function query(string $sql,array $args=[]):PDOStatement{global $db;$s=$db->prepare($sql);$s->execute($args);return $s;}
if($action==='register'){$name=field($p,'name',80);$email=field($p,'email',190);$roll=field($p,'roll',80);$pw=field($p,'password',200);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)fail('Use a valid email and password of at least 8 characters.');query('INSERT INTO users(name,email,roll,password_hash,role) VALUES(?,?,?,?,?)',[$name,$email,$roll,password_hash($pw,PASSWORD_DEFAULT),'student']);echo json_encode(['ok'=>true]);exit;}
if($action==='login'){if(time()-($_SESSION['attempt_start']??0)>300){$_SESSION['attempt_start']=time();$_SESSION['attempts']=0;}if(($_SESSION['attempts']??0)>=10)fail('Too many attempts. Wait five minutes.',429);$_SESSION['attempts']=($_SESSION['attempts']??0)+1;$email=field($p,'email',190);$u=query('SELECT * FROM users WHERE (email=? OR roll=?) AND role=?',[$email,$email,$p['role']??''])->fetch();if(!$u||!password_verify($p['password']??'',$u['password_hash']))fail('Incorrect role, email/roll number or password.',401);session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['attempts']=0;echo json_encode(['user'=>publicUser($u)]);exit;}
if($action==='logout'){$_SESSION=[];session_destroy();echo json_encode(['ok'=>true]);exit;}
$u=query('SELECT * FROM users WHERE id=?',[$_SESSION['uid']??0])->fetch();if(!$u)fail('Please sign in.',401);$uid=(int)$u['id'];$role=$u['role'];$now=gmdate('c');
function guard(bool $ok):void{if(!$ok)fail('Access denied.',403);}
function storeTicket(array $t):void{query('UPDATE complaints SET assigned=?,payload=? WHERE id=?',[$t['assigned'],json_encode($t),$t['id']]);}
if($action==='data'){$db->beginTransaction();$rows=query('SELECT * FROM complaints WHERE created < UTC_TIMESTAMP() - INTERVAL 48 HOUR FOR UPDATE')->fetchAll();foreach($rows as $row){$t=json_decode($row['payload'],true);if(!in_array($t['status'],['Resolved','Closed','Reopened / Escalated'],true)){$t['status']='Reopened / Escalated';$t['history'][]=['text'=>'Automatically escalated after 48 hours.','at'=>$now];storeTicket($t);}}$db->commit();$where=$role==='admin'?'1=1':($role==='student'?'student=?':'assigned=?');$tickets=array_map(fn($r)=>json_decode($r['payload'],true),query('SELECT payload FROM complaints WHERE '.$where.' ORDER BY created DESC',$role==='admin'?[]:[$uid])->fetchAll());$users=query($role==='admin'?'SELECT * FROM users':'SELECT * FROM users WHERE role="staff" OR id=?',$role==='admin'?[]:[$uid])->fetchAll();echo json_encode(['tickets'=>$tickets,'users'=>array_map('publicUser',$users),'categories'=>query('SELECT name FROM categories ORDER BY name')->fetchAll(PDO::FETCH_COLUMN),'notifications'=>[]]);exit;}
$db->beginTransaction();
if($action==='create'){guard($role==='student');query('SELECT id FROM users WHERE id=? FOR UPDATE',[$uid]);$n=query('SELECT COUNT(*) FROM complaints WHERE student=? AND created >= DATE(UTC_TIMESTAMP())',[$uid])->fetchColumn();if($n>=2)fail('Daily limit reached: 2 complaints per UTC day.');$campus=field($p,'campus',200);if(!in_array($campus,['Takatu Campus — Airport Road, Baleli, Quetta, Balochistan', 'City Campus — Jinnah Town, Samungli Road, Quetta, Balochistan', 'Chiltan Campus (Research) — Hazarganji, Quetta, Balochistan', 'Muslim Bagh Campus — Muslim Bagh, Balochistan', 'Zhob Campus — Zhob, Balochistan'],true))fail('Select a valid BUITEMS campus.');$title=field($p,'title',120);$location=field($p,'location',150);$description=field($p,'description',3000);$category=field($p,'category',60);if(!query('SELECT name FROM categories WHERE name=?',[$category])->fetch())fail('Invalid category.');$photos=$p['photos']??[];if(!is_array($photos)||count($photos)<1||count($photos)>3)fail('Attach 1 to 3 photos.');foreach($photos as $photo){if(!is_string($photo)||!preg_match('#^data:image/(jpeg|png|webp);base64,#',$photo))fail('Invalid photo.');$bytes=base64_decode(explode(',',$photo,2)[1],true);if($bytes===false||strlen($bytes)>2097152||!@getimagesizefromstring($bytes))fail('Invalid photo or photo exceeds 2 MB.');}$t=['id'=>'CMP-'.gmdate('Y').'-'.strtoupper(bin2hex(random_bytes(5))),'student'=>$uid,'campus'=>$campus,'assigned'=>null,'title'=>$title,'location'=>$location,'description'=>$description,'category'=>$category,'time'=>field($p,'time',40),'created'=>$now,'status'=>'In Progress','priority'=>'Medium','photos'=>$photos,'history'=>[['text'=>'Complaint submitted. Awaiting admin assignment.','at'=>$now]],'feedback'=>null];query('INSERT INTO complaints VALUES(?,?,?,?,?)',[$t['id'],$uid,null,gmdate('Y-m-d H:i:s'),json_encode($t)]);}
elseif(in_array($action,['assign','resolve','progress','feedback'],true)){$row=query('SELECT * FROM complaints WHERE id=? FOR UPDATE',[$p['id']??''])->fetch();if(!$row)fail('Ticket not found.',404);$t=json_decode($row['payload'],true);$active=!in_array($t['status'],['Closed','Resolved'],true);if($action==='assign'){guard($role==='admin'&&$active);$expert=query('SELECT * FROM users WHERE id=? AND role="staff"',[$p['assigned']??0])->fetch();if(!$expert||!in_array($p['priority']??'',['High','Medium','Low'],true))fail('Select an expert and priority.');$t['assigned']=(int)$expert['id'];$t['priority']=$p['priority'];$t['status']='In Progress';$text='Assigned to '.$expert['name'].' · '.$p['priority'].' priority.';}
elseif($action==='feedback'){guard($role==='student'&&$t['student']===$uid&&$t['status']==='Resolved');$like=($p['like']??false)===true;$t['feedback']=$like?'Like':'Unlike';$t['status']=$like?'Closed':'Reopened / Escalated';$text=$like?'Student confirmed the repair. Ticket closed.':'Student requested more work. Ticket reopened and escalated.';query('INSERT INTO feedback VALUES(?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE action=VALUES(action),updated=VALUES(updated)',[$t['id'],$uid,$t['feedback']]);}
else{guard($role==='staff'&&$t['assigned']===$uid&&$active);$text=field($p,'comment',2000);$t['status']=$action==='resolve'?'Resolved':'In Progress';if($action==='resolve')$t['resolved']=$now;}$t['history'][]=['text'=>$text,'at'=>$now];storeTicket($t);}
elseif($action==='category'){guard($role==='admin');$name=field($p,'name',60);$rows=query('SELECT * FROM complaints FOR UPDATE')->fetchAll();if(!empty($p['remove'])){foreach($rows as $r)if(json_decode($r['payload'],true)['category']===$name)fail('Category has existing complaints.');query('DELETE FROM categories WHERE name=?',[$name]);}elseif(!empty($p['old'])){query('UPDATE categories SET name=? WHERE name=?',[$name,$p['old']]);foreach($rows as $r){$t=json_decode($r['payload'],true);if($t['category']===$p['old']){$t['category']=$name;storeTicket($t);}}}else query('INSERT INTO categories VALUES(?)',[$name]);}
elseif($action==='user'){guard($role==='admin');if(!empty($p['remove'])){query('DELETE FROM users WHERE id=? AND role<>"admin"',[$p['id']??0]);}else{$name=field($p,'name',80);$email=field($p,'email',190);if(!filter_var($email,FILTER_VALIDATE_EMAIL))fail('Invalid email.');$department=substr(trim($p['department']??''),0,80);if(!empty($p['id']))query('UPDATE users SET name=?,email=?,department=? WHERE id=? AND role<>"admin"',[$name,$email,$department,$p['id']]);else{$pw=field($p,'password',200);if(strlen($pw)<8)fail('Password must have 8+ characters.');query('INSERT INTO users(name,email,roll,password_hash,role,department) VALUES(?,?,?,?,?,?)',[$name,$email,($p['roll']??'')?:null,password_hash($pw,PASSWORD_DEFAULT),($p['role']??'')==='staff'?'staff':'student',$department]);}}}
else fail('Unknown action.',404);
$db->commit();echo json_encode(['ok'=>true]);
}catch(PDOException $e){if(isset($db)&&$db->inTransaction())$db->rollBack();if($e->getCode()==='23000')fail('Email or roll number already exists, or this user has linked complaints.');fail('Database unavailable. Import schema.sql and check config.php.',503);}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();fail('The request could not be completed.',500);}
